use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit = 200000
    let mut comp = []
    for i in 0..(limit + 1) { comp.push(false) }
    let mut cnt = []
    let mut last = []
    let mut c = 0
    let mut l = -1
    for i in 0..(limit + 1) {
        if i >= 2 && !comp[i] {
            c += 1
            l = i
            let mut j = i * i
            while j <= limit {
                comp[j] = true
                j += i
            }
        }
        cnt.push(c)
        last.push(l)
    }
    let mut first = true
    let mut t = 0
    for line in text.lines() {
        let s = line.trim()
        if s == "" { continue }
        let v: int = s.parse::<int>().unwrap_or(0)
        if first {
            first = false
            t = v
            continue
        }
        if last[v] < 0 {
            println("0 none")
        } else {
            println("${cnt[v]} ${last[v]}")
        }
    }
}

